quests[45770] = { id = 45770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in den Schatten", description = "Jetzt müssen wir das Pferdegeschirr mithilfe materieller und immaterieller Mittel reinigen. Für die materiellen Mittel müssen wir nach Stratholme reisen.\n\nZur Blütezeit der Stadt, vor der Seuche, wurde dort heiliges Wasser produziert, mit dem man selbst die dunkelste Magie läutern konnte. Vielleicht finden wir dort noch ein paar unberührte Behältnisse.\n\nDann müssen wir das Geschirr nur noch mit ausreichend heiliger Kraft versehen, damit es den Willen von Totenschwurs Reittier Schattenmähne überwinden kann.\n\nBegebt Euch zum Dienstbotentor von Stratholme, wenn Ihr bereit seid.", sourceObjective = "Trefft Euch mit Lord Grayson Schattenbruch in Stratholme. Sucht, wenn Ihr drinnen seid, nach den Überresten von Baron Totenschwur und seinem Reittier und führt dann das Ritual zur Übernahme aus.", progress = "Euer Reittier ist zum Greifen nahe, Hochlord. Ich kann nur beten, dass es in Stratholme noch ausreichend heiliges Wasser gibt.", completion = "Ein bemerkenswertes Gefecht, meint Ihr nicht auch, Hochlord {name}? Hat mich an meine ruhmreichen Tage erinnert.\n\nVon jetzt an werden wir Stratholme besser im Auge behalten. Aber im Moment gibt es Wichtigeres.\n\nWir sollten mit der Zeremonie weitermachen, damit Ihr Euren Preis bekommt!", sourceObjectiveStatus = "unverified-source-field" }
quests[45771] = { id = 45771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles zur rechten Zeit", description = "Dank Eurer schnellen Reaktion erholt sich unser Orden, <Großmeister/Großmeisterin>.\n\nWir müssen uns nur noch um einen letzten Mönch kümmern, bevor es zu spät ist!", sourceObjective = "Bringt Eisenkörper Ponshu das kurierende Gebräu.", completion = "Großmeister {name}, meine alten Knochen werden allmählich müde. Unsere Zukunft hängt von Eurem fortwährenden Kampf gegen die Legion ab.\n\nSolange Ihr eine Flamme des Lichts in der Dunkelheit seid, besteht noch Hoffnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[45773] = { id = 45773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Class Hall - Maximillian of Northshire - Aqcuisition - Track Mail Sent" }
quests[45776] = { id = 45776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer braucht schon Schlüssel" }
quests[45785] = { id = 45785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Skarabäus", description = "Das Ereignis \"Ruf des Skarabäus\" findet heute statt. Sprecht mit Eurem Fraktionsanführer bei den Toren von Ahn'Qiraj.", sourceObjective = "Erstattet Kriegsherr Gorchuk in Silithus bericht.", completion = "Und wer seid Ihr? {name}?\n\nAhh... ja, Euren Namen habe ich schon mal gehört. Willkommen in Silithus, {name}.\n\nHeute feiern wir unsere Wurzeln als Söhne und Töchter Kalimdors. Aber nicht nur das: Wir beweisen auch, dass die Horde diese kümmerliche Allianz immer und immer wieder zerquetschen wird.\n\nSeid Ihr dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[45786] = { id = 45786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schmaus für die Hunde" }
quests[45787] = { id = 45787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Skarabäus", description = "Das Ereignis \"Ruf des Skarabäus\" findet heute statt. Sprecht mit Eurem Fraktionsanführer bei den Toren von Ahn'Qiraj.", sourceObjective = "Erstattet Feldmarschall Schneefall in Silithus bericht.", completion = "Und Ihr seid? {name}?\n\nAhh... ja, ich habe bereits von Euch gehört. Willkommen in Silithus, {name}.\n\nHeute feiern wir die Legenden der Kriegsgeschichte von Kalimdor. Mehr noch: Wir zeigen der Horde auch, dass die Allianz ihr immer und überall überlegen sein wird.\n\nKann ich auf Euch zählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[45788] = { id = 45788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sprecher erwartet Euch", description = "<Hohepriester/Hohepriesterin>, der Netherlichttempel meldet einen höchst ungewöhnlichen Gast: Magni Bronzebart, der Sprecher selbst!\n\nWas könnte er von unserem Orden wollen? Ihr solltet besser zurück zum Tempel eilen. Wir werden hier die Stellung halten.", sourceObjective = "Sprecht mit Betild Tiefenamboss im Netherlichttempel.", completion = "Danke, dass Ihr so schnell kommen konntet, Hohepriester. König Magni, oder besser gesagt, \"der Sprecher\", glaubt, ein geheimes Titanengewölbe gefunden zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[45789] = { id = 45789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versunkene Kammer", description = "Seid gegrüßt, <Hohepriester/Hohepriesterin>. Der Sprecher hat uns von einer Art Anrufung aus den Tiefen Azeroths berichtet.\n\nDiese Stimme berichtet ihm von einem vergessen Titanengewölbe in der Nähe des Mahlstroms. Wir wissen nicht, was sich darin befindet, aber es soll mit dem Licht und mit Euch zu tun haben!\n\nBrann hat ein Transportmittel organisiert, das vor der Küste von Azsuna auf Euch wartet. Ich werde natürlich auch mitkommen und kartografieren. So eine Möglichkeit darf ich mir nicht entgehen lassen!", sourceObjective = "Nehmt Branns Schiff in Azsuna zur versunkenen Kammer.", progress = "Ich bekomm 'ne Gänsehaut davon, als Erster in so ein unerforschtes Titanengewölbe reinmarschieren zu dürfen!", completion = "Es ist uns eine große Ehre, Euch die Zügel dieses edlen Rosses zu überreichen, Hohepriester. Ich danke Euch, dass Ihr uns anführt. Ihr seid wahrlich vom Licht gesegnet. Und wir dürfen uns gesegnet fühlen, Euch zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[45790] = { id = 45790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Almai", sourceObjective = "Ich werde Braumeisterin Blanche vermissen. Sie hat mich gelehrt, meinen Träumen zu folgen.\n\nUnd ich wollte schon immer das Nebelwirken erlernen...\n\nGroßmeister {name}. Wenn Ihr mich haben wollt, werde ich Euch und Euren Orden gegen alles verteidigen, das uns schaden will.", sourceObjectiveStatus = "unverified-source-field" }
quests[45791] = { id = 45791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaterial" }
quests[45792] = { id = 45792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okkultistenattacke" }
quests[45793] = { id = 45793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okkultistenattacke" }
quests[45794] = { id = 45794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Rat informieren", description = "Ich werde mich um den Gefangenen kümmern, aber Ihr solltet Euch zurück in die Schreckensnarbe begeben. \n\nErzählt den anderen von unserer Entdeckung. Wir werden ihre Hilfe gegen Kanrethad an der Verheerten Küste brauchen.", sourceObjective = "Kehrt zu Shinfel Pestschwur in der Schreckensnarbe zurück.", completion = "Danke, dass Ihr mir die Neuigkeiten von Jubeka überbracht habt. Es ist wahrlich der perfekte Zeitpunkt.\n\nWir haben Informationen über Kanrethads Aufenthaltsort erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45795] = { id = 45795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtvolle Präsenz", description = "Die Dämonen scheinen sich innerhalb des Tempels eine uralte Macht zunutze zu machen. Es ist ihnen gelungen, diesen heiligen Boden mit ihrer Teufelsmagie zu verseuchen und zu verderben.\n\nWir müssen diese Dämonen vertreiben, bevor wir unseren finalen Angriff starten.", sourceObjective = "Schlagt die Legionsbedrohung im Tempel der Tausend Lichter zurück und tötet dann Portalhüter V'thaal und Zor'thaduun.", completion = "Unser Kampf hier ist noch nicht vorbei, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[45796] = { id = 45796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtung des Nests", description = "Wir müssen Tugars Plan ein Ende setzen. Diese Abscheulichkeiten gehören vernichtet und ihre Quelle ebenso!\n\nIch weiß vermutlich, wo sie sind. Unweit von hier hatte sich eine Gruppe neutraler Drogbar niedergelassen, doch sie wurden durch einen vereinten Angriff von Dämonen und teuflisch verderbten Tauren vertrieben. Das muss der Ort sein.\n\nBegebt Euch dorthin und beendet ihre teuflische Monsterproduktion an der Quelle!", sourceObjective = "Betretet die Höhlen der Teufelstotems und durchkreuzt Tugars Pläne.", completion = "Ihr habt Donnertotem gerettet und wir stehen noch tiefer in Eurer Schuld.\n\nEine Schande, dass Tugar nicht dort war. Solange er lebt, werden wir weiter in Gefahr schweben.\n\nIch werde alles in meiner Macht Stehende tun, um ihn zu finden. Und dann werden wir dem ein Ende setzen... gemeinsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[45797] = { id = 45797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel mit dem grünen Feuer" }
quests[45798] = { id = 45798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War'zuul der Provokateur", description = "Dort oben isst so ein widerlicher Dämonenlord, der schon seit Sstunden herumbrüllt.\n\nKönntet Ihr ihm bitte endlich dass Maul stopfen? Ich bekomme ganz grausame Kopfschmerzen davon!", sourceObjective = "Tötet War'zuul den Provokateur.", completion = "Wurde auch langsam Zeit, dasss Ihr den Dämon ruhigstellt. Bessten Dank...", sourceObjectiveStatus = "unverified-source-field" }
quests[45799] = { id = 45799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verschleierter Pfad durch die Zeit", description = "Der verschleierte Stern lässt sein Flackern durch die flüsternden Wogen der gespenstischen Nebel gleiten. Wie ein düsterer Schleier legt sich das Schauspiel über die Geheimnisse und Gefahren des Landes und eröffnet neue Pfade zu fernen Orten, gar Zeiten, bis sein Lichtspiel still entschwindet. Kein Weiser kann die Natur dieses Omens wahrhaft begreifen, doch das Glück ist bekanntlich mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45801] = { id = 45801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antonidas' Privatprojekt", description = "<Erzmagier/Erzmagierin>, ich habe etwas gefunden, das Euch vielleicht interessieren könnte: ein altes Tagebuch des verstorbenen Erzmagiers Antonidas. Darin beschreibt er ein Projekt, das wir vielleicht vollenden können.\n\nEs handelt sich dabei um eine Flugscheibe, die sich an die magische Abstimmung des Reiters anpasst.\n\nIch brauche allerdings Eure Hilfe beim Zusammentragen der Teilstücke. Wenn ich es richtig verstanden habe, hat er sie im Laufe der Jahre engen Freunden und Verbündeten überlassen. Vielleicht könnt Ihr sie davon überzeugen, uns diese Teilstücke zu überlassen.", sourceObjective = "Bergt die drei Scheiben von Antonidas' unvollendetem Projekt und kehrt dann zu Kalec in Eurer Ordenshalle zurück. Erzmagier John Nicholas am Purpursalon in Nordend über die Trischeibe des Arkanen. Sprecht mit Khadgar über Trischeibe des Feuers. Und sprecht mit Erzmagier Cedric in der Nähe des Dalarankraters über die Trischeibe des Frostes.", sourceObjectiveStatus = "unverified-source-field" }
quests[45802] = { id = 45802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antonidas' Privatprojekt", description = "<Erzmagier/Erzmagierin>, ich habe etwas gefunden, das Euch vielleicht interessieren könnte: ein altes Tagebuch des verstorbenen Erzmagiers Antonidas. Darin beschreibt er ein Projekt, das wir vielleicht vollenden können.\n\nEs handelt sich dabei um eine Flugscheibe, die sich an die magische Abstimmung des Reiters anpasst.\n\nIch brauche allerdings Eure Hilfe beim Zusammentragen der Teilstücke. Wenn ich es richtig verstanden habe, hat er sie im Laufe der Jahre engen Freunden und Verbündeten überlassen. Vielleicht könnt Ihr sie davon überzeugen, uns diese Teilstücke zu überlassen.", sourceObjective = "Bergt die drei Scheiben von Antonidas' unvollendetem Projekt und kehrt dann zu Kalec in Eurer Ordenshalle zurück. Erzmagier John Nicholas am Purpursalon in Nordend über die Trischeibe des Arkanen. Sprecht mit Khadgar über Trischeibe des Feuers. Und sprecht mit Erzmagier Cedric in der Nähe des Dalarankraters über die Trischeibe des Frostes.", sourceObjectiveStatus = "unverified-source-field" }
quests[45803] = { id = 45803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antonidas' Privatprojekt", description = "<Erzmagier/Erzmagierin>, ich habe etwas gefunden, das Euch vielleicht interessieren könnte: ein altes Tagebuch des verstorbenen Erzmagiers Antonidas. Darin beschreibt er ein Projekt, das wir vielleicht vollenden können.\n\nEs handelt sich dabei um eine Flugscheibe, die sich an die magische Abstimmung des Reiters anpasst.\n\nIch brauche allerdings Eure Hilfe beim Zusammentragen der Teilstücke. Wenn ich es richtig verstanden habe, hat er sie im Laufe der Jahre engen Freunden und Verbündeten überlassen. Vielleicht könnt Ihr sie davon überzeugen, uns diese Teilstücke zu überlassen.", sourceObjective = "Bergt die drei Scheiben von Antonidas' unvollendetem Projekt und kehrt dann zu Kalec in Eurer Ordenshalle zurück. Erzmagier John Nicholas am Purpursalon in Nordend über die Trischeibe des Arkanen. Sprecht mit Khadgar über Trischeibe des Feuers. Und sprecht mit Erzmagier Cedric in der Nähe des Dalarankraters über die Trischeibe des Frostes.", sourceObjectiveStatus = "unverified-source-field" }
