quests[45810] = { id = 45810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gnome haben unsere Bomben geklaut!" }
quests[45811] = { id = 45811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goblins haben unsere Bomben geklaut!" }
quests[45812] = { id = 45812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Val'sharah", description = "Die Legion zieht über unser Land. Findet ihre Streitkräfte und schaltet die Bedrohung aus, bevor es zu spät ist!", sourceObjective = "Schlagt die Streitkräfte der Brennenden Legion in ganz Val'sharah zurück.", completion = "Wir müssen unseren Kampf fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45813] = { id = 45813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, wo seid Ihr, meine Teure?!", description = "Welch betrübliches Schicksal! Hier stehen wir mit dem Schmuck, der meiner Geliebten die Freiheit erkaufen soll, und sie ist einfach verschwunden! Wir müssen die Gäste dieses feinen Etablissements danach befragen, ob sie wissen, was ihr zugestoßen sein könnte.", sourceObjective = "Helft, Dolorias \"Illusion\" aufrechtzuerhalten und hört Euch im Gasthaus um, um zu erfahren, wohin Doloria verschwunden ist.", completion = "Man hat sie also entführt, aber wir werden nicht rasten. Begleitet mich als Anhänger, führt meine Truppen an, absolviert Missionen für mich! Zusammen werden wir sie finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[45815] = { id = 45815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogue" }
