quests[45831] = { id = 45831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter" }
quests[45833] = { id = 45833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Piratenbucht", description = "Da wir an der Verheerten Küste mittlerweile Fortschritte gemacht haben, denke ich, dass es jetzt an der Zeit für einige der subtileren Taktiken der Ungekrönten ist.\n\nWir haben von einer großen Höhle auf dem Festland erfahren, wo mächtige Dämonen Pläne für unseren Niedergang schmieden. Tess und Tethys haben einen Plan ausgearbeitet, aber dafür brauchen sie Eure Hilfe. Sie warten auf Euch in des Toten Manns Bucht in Azsuna.", sourceObjective = "Trefft Euch mit Tess Graumähne und Tethys in des Toten Manns Bucht in Azsuna.", completion = "Macht Euch bereit, Schattenklinge. Wir haben etwas zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45834] = { id = 45834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Seelen", description = "Die Würdigen Odyns werden von Seelenbrunnen gefangen gehalten, die sich überall auf dem Ewigen Schlachtfeld befinden. Sie waren dazu berufen, Valarjar zu werden, bevor man ihnen ihre Zukunft stahl.\n\nIhr könnt sie jetzt an ihre angestammten Plätze zurückbringen. Zerstört die Seelenbrunnen, um sie freizusetzen!", sourceObjective = "Befreit 15 gestohlene Seelen.", completion = "Wenn die Valarjar die Vorhut anführen, werden unsere Kämpfe ruhmreich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[45835] = { id = 45835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefälschte Befehle", description = "Sobald Ihr Prix ausschaltet, wird sich die Nachricht wie ein Lauffeuer unter der Mannschaft ausbreiten. Tethys hat ihre Handschrift gefälscht und ein paar Befehle geschrieben, um die Leute wegzuschicken. Das verschafft uns etwas Zeit.\n\nPlatziert diese Befehle an den markierten Plätzen. Es wird nicht lange dauern, bis Euer Tun Früchte trägt.", sourceObjective = "Platziert die gefälschten Befehle an den markierten Plätzen.", completion = "Sie sind direkt an uns vorbeigelaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45836] = { id = 45836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zu Jorach", description = "Und damit ist die erste Phase des Plans abgeschlossen. Am besten kehren wir jetzt zu Jorach zurück und erzählen ihm davon.", sourceObjective = "Kehrt zu Lord Jorach Rabenholdt in der Halle der Schatten zurück.", completion = "Willkommen zurück, Schattenklinge. Ich gehe davon aus, dass Ihr das Schießpulver besorgt habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[45837] = { id = 45837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriechende Teufelsmagie" }
quests[45838] = { id = 45838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Azsuna", description = "Die Dämonen stellen eine existenzielle Bedrohung für unser Land und all seine Einwohner dar.\n\nEliminiert diese Bedrohung, bevor es zu spät ist.", sourceObjective = "Schlagt die Streitkräfte der Brennenden Legion in ganz Azsuna zurück.", completion = "Ich befürchte, unser Kampf ist noch lang nicht vorüber. Wir müssen unseren Angriff fortführen, bevor die Legion aus ihrer Stellung im Tempel der Tausend Lichter ausrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[45839] = { id = 45839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Sturmheim", description = "Der ewige Feind unserer Welt, die Brennende Legion, wagt es, Sturmheim anzugreifen!\n\nChampion, jetzt ist Eure Tapferkeit gefragt! Findet und vernichtet die Streitkräfte der Legion!", sourceObjective = "Schlagt die Streitkräfte der Brennenden Legion in ganz Sturmheim zurück.", completion = "Gleich hinter diesen Klippen sammeln sich die Streitkräfte der Legion für ihren Angriff. Ihre Streitmacht wird von Minute zu Minute größer.\n\nWir müssen bald angreifen, bevor wir überwältigt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[45840] = { id = 45840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Hochberg", description = "In all meinen Jahren habe ich viele verstörende und bedrohliche Sachen gesehen, aber noch nie eine solche Geringschätzung für das Leben selbst.\n\nAuch wenn diese Dämonen unser Land verbrennen und unserem Volk Leid zufügen, dürfen wir nicht einfach zusehen, wie sie alles bedrohen, wofür wir so hart gekämpft haben.\n\nMacht Euch bereit, {name}. Es wird Zeit, dass wir uns in die Schlacht mit der Brennenden Legion werfen!", sourceObjective = "Schlagt die Streitkräfte der Brennenden Legion am ganzen Hochberg zurück.", completion = "Tut mir leid, {name}. Aviash und ich wollten Euch nicht zu nahe treten. In Zeiten wie diesen kann man nicht vorsichtig genug sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[45841] = { id = 45841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein triumphaler Bericht", description = "Ihr solltet zu den Kirin Tor zurückkehren. Zweifellos möchten sie die guten Neuigkeiten erfahren!", sourceObjective = "Sprecht mit Erzmagierin Modera in Dalaran.", completion = "Ich bin erleichtert, dass Ihr Euch um die unmittelbare Bedrohung gekümmert habt. Wir haben schon so kaum genug Ressourcen für die Verheerte Küste!\n\nDennoch haben wir etwas für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[45842] = { id = 45842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe der Sechs", description = "{name}, ohne Euch würden einige der stärksten Agenten der Legion immer noch Azeroth durchstreifen und das könnte alles unterminieren, was wir in diesem Krieg erreicht haben.\n\nEure Taten verdienen mehr als nur Anerkennung.\n\nWir würden Euer Heldentum im Angesicht dieser Finsternis gerne offiziell mit einem Anteil an unserer Macht belohnen, wenn Ihr sie denn annehmen möchtet.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", progress = "Seid Ihr bereit?", completion = "Wir hoffen, dass die gesteigerte Macht Eurer Waffe sich an der Verheerten Küste und darüber hinaus als nützlich erweisen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[45843] = { id = 45843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Omen", description = "Alleine werden wir Kruul nicht bezwingen können.\n\nSobald das Portal stabilisiert ist, werde ich eine Nachricht aussenden, damit wir den Hochlord seiner gerechten Strafe zuführen können.\n\nIn der Zwischenzeit solltet Ihr die Kirin Tor über Vazuuns Tod in Kenntnis setzen... und über Kruuls Rückkehr.", sourceObjective = "Sprecht mit Erzmagierin Modera in Dalaran.", completion = "Glück gehabt?", sourceObjectiveStatus = "unverified-source-field" }
quests[45844] = { id = 45844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antonidas' Privatprojekt", description = "Erzmagier Kalec bittet Euch, in die Halle des Wächters zurückzukehren. Er hat etwas herausgefunden, über das er dringend mit Euch sprechen möchte.\n\nBitte sucht ihn so bald wie möglich auf.", sourceObjective = "Sprecht mit Erzmagier Kalec in der Halle des Wächters.", completion = "Erzmagier, ich habe etwas gefunden, dass Euch vielleicht interessieren könnte: ein altes Tagebuch des verstorbenen Erzmagiers Antonidas. Darin beschreibt er ein Projekt, das wir vielleicht für ihn vollenden können.\n\nEs handelt sich dabei um eine Flugscheibe, die sich an die magische Spezialisierung des Reiters anpasst.\n\nIch brauche allerdings Eure Hilfe beim Zusammentragen der Teilstücke. Wenn ich es richtig verstanden habe, hat er sie im Laufe der Jahre engen Freunden und Verbündeten überlassen. Vielleicht könnt Ihr sie davon überzeugen, uns diese Teilstücke zu überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45845] = { id = 45845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer im Inneren", description = "Das erste Teilstück, von dem er sprach, war das des Feuers. Er erfüllte es mit Feuermagie, während er den Eingang zum Geschmolzenen Kern untersuchte.\n\nDie Macht, die hindurchströmte, war allerdings zu stark und er konnte sie nicht beherrschen, also bat er Khadgar, es nach Karazhan zu bringen und nachzusehen, ob er Bücher zum Thema Feuerbeherrschung finden könne.\n\nVielleicht solltet Ihr mit Khadgar sprechen und herausfinden, was aus der Scheibe wurde.", sourceObjective = "Sprecht mit Khadgar über die Trischeibe des Feuers. Folgt seinen Anweisungen, nachdem Ihr mit ihm gesprochen habt.", progress = "Hat sich Khadgar daran erinnern können, was er mit dem Teilstück angestellt hat?", completion = "Ihr habt es gefunden! Und genau wie Antonidas schrieb, ist es immer noch von mächtiger Feuermagie erfüllt!", sourceObjectiveStatus = "unverified-source-field" }
quests[45846] = { id = 45846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchgefroren", description = "Das nächste Teilstück, das Antonidas erschuf, wurde mit Frostmagie erfüllt. Er schrieb von einem Ritual, um Frostenergie gemeinsam mit Erzmagier Cedric in die Scheibe zu kanalisieren, aber ihre gemeinsame Stärke zwang zu viel Energie hinein.\n\nWenn ich mich recht erinnere, hilft Cedric in der Nähe des Kraters, wo Dalaran einst stand, bei der Beaufsichtigung des Wiederaufbaus von Dalaran.\n\nHoffentlich weiß er, wo die Scheibe zu finden ist.", sourceObjective = "Sprecht mit Erzmagier Cedric in der Nähe des Dalarankraters über die Trischeibe des Frostes.", progress = "Nach der Katastrophe, die Dalarans ursprüngliche Heimat heimgesucht hat... wer weiß da schon, wo diese Scheibe sein mag.", completion = "Oger hatten das Scheibenstück entwendet? Ich glaube, diese Bestien nehmen auch alles, dessen sie habhaft werden können.\n\nWie auch immer, es ist ausgezeichnet, dass Ihr es finden konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[45847] = { id = 45847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz in der Nähe", description = "Das dritte Teilstück der Scheibe wurde mit Antonidas' eigener arkaner Magie erfüllt. Er tat dies auf dem Höhepunkt seiner Macht, aber genau wie bei den beiden anderen Scheiben konnte er seine Arbeit daran nicht beenden.\n\nEr schrieb, dass er das Stück Erzmagierin Celindra gegeben habe...\n\nIst sie nicht die Portallehrerin hier in Dalaran? Sie muss wissen, wo das Teilstück ist!\n\nSchnell, geht und sprecht mit ihr.", sourceObjective = "Sprecht mit Erzmagierin Celindra über die Trischeibe des Arkanen hier in Dalaran.", progress = "Hatte sie das Teilstück?", completion = "Wenn man bedenkt, dass es die ganze Zeit hier in Dalaran war!", sourceObjectiveStatus = "unverified-source-field" }
quests[45848] = { id = 45848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Piraten würdig", sourceObjective = "Krächz! Tethys ist doof! Schlechter Pirat! Schlechter Pirat!\n\n{name} besserer Pirat, kraaaah! Gehe jetzt mit Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[45849] = { id = 45849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "3+ Targets Trait Complete" }
quests[45850] = { id = 45850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AoE Chosen" }
