quests[45856] = { id = 45856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um Val'sharah", description = "Von Beginn dieser Angriffe an hatte ich das Gefühl, dass die Dämonen unsere Pläne kennen... dass sie jeden unserer Schritte vorausahnen. Wenn wir dem ein Ende bereiten wollen, müssen wir unsere Angriffe mitten ins Herz der Bestie führen.\n\nUnsere Bemühungen haben gezeigt, dass diese Schlachten nicht allein durch Tapferkeit gewonnen werden, sondern durch Willen und Opferbereitschaft. Ich bitte Euch, noch einmal mit Euren Verbündeten auf dem Schlachtfeld zu stehen, um diesem Wahnsinn ein Ende zu bereiten.", sourceObjective = "Besiegt Schreckenswesir Gra'tork in Val'sharah.", completion = "Ihr habt Opfer für unser Land gebracht, tapferer {class}.\n\nEure Beharrlichkeit hat unsere Brüder und Schwestern dazu inspiriert, sich gegen die Brennende Legion zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45861] = { id = 45861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe der Sechs", description = "{name}, ohne Euch würden einige der stärksten Agenten der Legion immer noch Azeroth durchstreifen und das könnte alles unterminieren, was wir in diesem Krieg erreicht haben.\n\nEure Taten verdienen mehr als nur Anerkennung.\n\nWir würden Euer Heldentum im Angesicht dieser Finsternis gerne offiziell mit einem Anteil an unserer Macht belohnen, wenn Ihr sie denn annehmen möchtet.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", progress = "Seid Ihr bereit?", completion = "Wir hoffen, dass die gesteigerte Macht Eurer Waffe sich an der Verheerten Küste und darüber hinaus als nützlich erweisen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[45862] = { id = 45862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe der Sechs", description = "{name}, ohne Euch würden einige der stärksten Agenten der Legion immer noch Azeroth durchstreifen und das könnte alles unterminieren, was wir in diesem Krieg erreicht haben.\n\nEure Taten verdienen mehr als nur Anerkennung.\n\nWir würden Euer Heldentum im Angesicht dieser Finsternis gerne offiziell mit einem Anteil an unserer Macht belohnen, wenn Ihr sie denn annehmen möchtet.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", progress = "Seid Ihr bereit?", completion = "Wir hoffen, dass die gesteigerte Macht Eurer Waffe sich an der Verheerten Küste und darüber hinaus als nützlich erweisen wird.", sourceObjectiveStatus = "unverified-source-field" }
