quests[45873] = { id = 45873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Etrigg", sourceObjective = "Emotionale Reden liegen mir nicht, Schlachtenfürst {name}, also werde ich mich kurz fassen. \n\nIch verdanke Euch mein Leben. Meine Äxte stehen Euch zu Diensten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45876] = { id = 45876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lord Darius Crowley", sourceObjective = "Ihr seid ein inspirierender Anführer, Schlachtenfürst {name}. Ich werde Euch nach Argus und zurück folgen, wenn Ihr mich mitnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45878] = { id = 45878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungestrafte Auslöschung" }
quests[45883] = { id = 45883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vergehen des Feuerlords", description = "Glimmeron ruft von der anderen Seite des Schlachtfelds nach Euch, <Schamane/Schamanin>. Nun ist es sein Reich, das in Gefahr ist.\n\nEs scheint dringend zu sein. Ich werde hier aufräumen.", sourceObjective = "Meldet Euch bei Feuerlord Glimmeron im Glutstrom.", completion = "Ich werde eine solche Anmaßung nicht dulden!", sourceObjectiveStatus = "unverified-source-field" }
