quests[45889] = { id = 45889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prideful Gladiator's Leather Armor" }
quests[45890] = { id = 45890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorfahren und Feinde", description = "Nichts will ich mehr, als mich bei unserer Offensive an der Verheerten Küste zu beweisen, doch langsam zweifle ich daran, dass ich würdig bin.\n\nIch habe nämlich in den von mir entschlüsselten dämonischen Runen das Siegel meiner Familie entdeckt. Ich kann mir einfach nicht erklären, woher die Legion das Mondfangwappen kennen würde, doch ich habe keinen Zweifel, dass Ihr die Verbindung zwischen meinen Vorfahren und unseren Feinden aufdecken könnt.\n\nAlles, was von ihrem Dorf verblieb, befindet sich in Val'sharah.", sourceObjective = "Begebt Euch nach Val'sharah zum Heim von Delas' Vorfahren und beschafft Relikte aus ihrer Vergangenheit.", completion = "Was habt Ihr hier zu suchen? Wollt Ihr plündern, was die Harpyien nicht in die Krallen bekommen haben?", sourceObjectiveStatus = "unverified-source-field" }
