quests[45902] = { id = 45902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschenk der Wichtelmutter", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", completion = "Es ist nur ein kleiner Lohn für das, was Ihr vollbracht habt, doch ich hoffe, es reicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[45903] = { id = 45903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prideful Gladiator's Ringmail Armor" }
quests[45904] = { id = 45904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk der Gottkönigin", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", completion = "Ich kann Euch nicht genug danken, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[45905] = { id = 45905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kruuls Geschenk", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[45906] = { id = 45906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarods Geschenk", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", completion = "Wenn das alles vorüber ist, kann der Rat Euch hoffentlich gebührend danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[45907] = { id = 45907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prideful Gladiator's Satin Armor" }
quests[45908] = { id = 45908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylems Geschenk", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", completion = "Euer Talent in diesen Dingen ist verblüffend!", sourceObjectiveStatus = "unverified-source-field" }
quests[45909] = { id = 45909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navarroggs Geschenk", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", completion = "Wir hoffen, dass die gesteigerte Macht Eurer Waffe sich an der Verheerten Küste und darüber hinaus als nützlich erweisen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[45910] = { id = 45910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raests Geschenk", description = "Obgleich wir Euch bereits so viel Macht wie möglich verliehen haben, würden wir Euch gerne eine... optische Aufwertung Eures Artefakts zukommen lassen.\n\nIm Namen des Rats der Sechs, Dalarans und Azeroths möchten wir Euch erneut danken, {name}.", sourceObjective = "Erhebt Eure Waffe und erhaltet das Geschenk des Rates der Sechs in der Violetten Zitadelle.", completion = "Erneut habt Ihr bewiesen, welch fähiger Agent Ihr im Kampf gegen die Legion seid.", sourceObjectiveStatus = "unverified-source-field" }
