quests[45913] = { id = 45913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Shore Main Questline: Tracking Flag" }
quests[45914] = { id = 45914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ch 5 Soulstone Shielded Tracking Quest" }
quests[45915] = { id = 45915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor und eine gute Freundin. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich für uns alle, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie beim Militanten Mystiker gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", sourceObjectiveStatus = "unverified-source-field" }
quests[45916] = { id = 45916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akolyth in Gefahr", description = "In Wahrheit weiß der Rat nur wenig von Agatha, aber sie ist mehr als nur ein durchschnittlicher Sukkubus. Sie hat viele Verbündete bei den Sayaad und ist bekannt dafür, Armeen von Wichteln zu befehligen, die in Massen ihre Feinde überwältigen.\n\nSie aufzuspüren wäre töricht, aber Ritssyn Flammengroll bleibt nichts schuldig.\n\nKommt, lasst uns untersuchen, über welche Teufelskräfte Eure kleine Magierin gestolpert ist...", sourceObjective = "Helft Ritssyn dabei, Levias Ritual zu untersuchen.", progress = "Haltet diese Wichtel von mir fern!", completion = "Es ist beeindruckend, wie viel Macht Levia in dieses Portal kanalisiert hat, auch wenn es unnötig war. Unglücklicherweise wird es wahrscheinlich zusammenbrechen und uns mitnehmen, wenn wir es nicht stabilisieren.\n\nEs reicht wohl, zu sagen, dass das Eurer Mission ein schnelles Ende bereiten würde.\n\nIch muss mich konzentrieren, um es offenzuhalten, also brauche ich Eure Hilfe...", sourceObjectiveStatus = "unverified-source-field" }
quests[45917] = { id = 45917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer der Nase nach", description = "Ihr werdet ohne mich durch das Portal gehen müssen, {class}. Ich habe Euch geholfen, den Aufenthaltsort Eurer Magierin zu finden, also betrachte ich meine Schuld Modera gegenüber als abgegolten.\n\nIch werde Euch allerdings einen meiner Teufelshunde leihen, um die Magierin aufzuspüren. Wenn sie so mächtig ist, wie Modera sagt, wäre es in unser aller Interesse, wenn wir nicht zulassen, dass Agatha sie behält.\n\nViel Glück, {class}, und versucht, Fhambar unversehrt zurückzubringen.", sourceObjective = "Folgt Fhambar zu Levias Aufenthaltsort.", completion = "Was... Was ist los?\n\nWer seid Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[45921] = { id = 45921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'xur" }
