quests[45970] = { id = 45970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Dienstes" }
quests[45971] = { id = 45971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllisches Phänomen", description = "Habt Ihr das gehört, <Schamane/Schamanin>? Das ist das Grollen der Erde, während sie versucht, gegen den Willen der Legion anzukämpfen. Ihre geistig minderbemittelten Eredar versuchen, die Mächte Azeroths ihrem Willen zu beugen.\n\nWie kann die Legion nur zu denken wagen, sie könne meine Domäne verderben? Sie hat ihre Höllenbestien aus dem Stein Azeroths erschaffen... aus MEINEM Stein! Jetzt versucht sie, diese neuen Höllenbestien zum Leben zu erwecken.\n\nSabotiert ihre närrischen Rituale. Zerschmettert sie! Zeigt ihr die wahre Macht von Azeroth!", sourceObjective = "Unterbrecht 3 Höllenbestienrituale.", completion = "Was habe ich gelacht, als ihre Höllenbestien zerfielen. Sie sind wieder Teil des Gesteins von Azeroth, wo sie hingehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[45972] = { id = 45972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verfluchte Dickicht", description = "Es gibt eine letzte Aufgabe für Euch und den Verdammnisstein. Donneraan wird Euch alles erklären.", sourceObjective = "Sprecht mit Donneraan.", sourceObjectiveStatus = "unverified-source-field" }
quests[45973] = { id = 45973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkontrollierte Macht" }
quests[45974] = { id = 45974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Warnung", description = "<Der Soldat ist verwundet und blass im Gesicht. Offensichtlich hat er große Schmerzen.>\n\nHielten mich gefangen... seit dem Angriff auf... die Verheerte Küste...\n\n<Er zittert.>\n\nDie Dämonen... sie... sie sammeln sich... bereiten sich vor...\n\nMusste fliehen... die anderen warnen. Wir müssen... sie aufhalten!", sourceObjective = "Sprecht mit Lord Maxwell Tyrosus.", completion = "Seid gegrüßt, Hochlord. Mir wurde gerade von dem verwundeten Soldaten berichtet, der von der Verheerten Küste fliehen konnte.\n\nIch will mir gar nicht ausmalen, was er alles durchgemacht haben muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[45975] = { id = 45975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Tyrosus senkt seinen Blick zu Boden.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
