quests[45994] = { id = 45994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Kor'vas senkt ihren Blick.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45995] = { id = 45995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Warnung", description = "<Der Soldat ist verwundet und blass im Gesicht. Offensichtlich hat er große Schmerzen.>\n\nSie... hielten mich gefangen... seit dem Angriff auf... die Verheerte Küste...\n\n<Er zittert.>\n\nDie Dämonen... sie... sie sammeln sich... bereiten sich vor...\n\nMusste fliehen... Euch warnen. Wir müssen... sie aufhalten!", sourceObjective = "Sprecht mit Berater Sevel.", completion = "Seid gegrüßt, Scharfseherin. Mir wurde gerade von dem verwundeten Soldaten berichtet, der von der Verheerten Küste fliehen konnte.\n\nIch will mir gar nicht ausmalen, was er alles durchgemacht haben muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[45996] = { id = 45996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Sevel senkt seinen Blick.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45997] = { id = 45997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Warnung", description = "<Die Soldatin ist verwundet und blass im Gesicht. Offensichtlich hat sie große Schmerzen.>\n\nHielten mich gefangen... seit dem Angriff auf... die Verheerte Küste...\n\n<Sie zittert.>\n\nDie Dämonen... sie... sie sammeln sich... bereiten sich vor...\n\nMusste fliehen... die anderen warnen. Wir müssen... sie aufhalten!", sourceObjective = "Sprecht mit Erzmagierin Melis.", completion = "Seid gegrüßt, Erzmagier. Mir wurde gerade von der verwundeten Soldatin berichtet, die von der Verheerten Küste fliehen konnte.\n\nIch will mir gar nicht ausmalen, was sie alles durchgemacht haben muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[45998] = { id = 45998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Melis senkt ihren Blick.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45999] = { id = 45999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion Assault" }
quests[46000] = { id = 46000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran bewaffnen", description = "Kathra'natir kann nichts dagegen ausrichten, dass wir uns seine Energie im Seelenstein der Nachtgeborenen zunutze machen. Bisher hatten wir Glück: Unsere Verbündeten haben verhindert, dass sich die Botschaft über die Sabotage verbreitet.\n\nWir sollten unmittelbar, und solange wir noch das Glück auf unserer Seite haben, Dalarans Waffen reparieren.\n\nOh, übrigens: Die Waffenplattform ist recht unzugänglich. Ihr leidet doch wohl nicht unter Höhenangst? Ich werde ein Portal öffnen.", sourceObjective = "Reist durch Aethas' Portal zur Dalaranspitze.", completion = "Gut gemacht, Erzmagier {name}! Dalaran kann sich wieder verteidigen.\n\nNun müssen wir unseretwillen hoffen, dass die Schilde von Kathra'natirs Gefängnis nicht versagen, bevor wir eine sicherere Lösung gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
