quests[46020] = { id = 46020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalleindämmung", description = "In meiner Obhut ist Kanrethad sicher, doch wir müssen etwas mit den Kristallen tun, die seine Teufelsmagie beinhalten.\n\nSollten sie zerbrechen, würde die enthaltene Energie zu unserem Freund zurückfinden. Ich muss wohl nicht betonen, wie verheerend ein solches Ereignis wäre.\n\nIch werde die Kristalle einsammeln und Euch in der Schreckensnarbe treffen.", sourceObjective = "Trefft Jubeka Schattenbrecher in der Schreckensnarbe.", completion = "Hier können die Mitglieder des Rates sicher über die Kristalle wachen.\n\nKanrethad hat sich noch nicht gänzlich erholt, doch kann er bereits wieder sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46021] = { id = 46021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thel'draz" }
quests[46022] = { id = 46022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Warnung", description = "<Die Soldatin ist verwundet und blass im Gesicht. Offensichtlich hat sie große Schmerzen.>\n\nHielten mich gefangen... seit dem Angriff auf... die Verheerte Küste...\n\n<Sie zittert.>\n\nDie Dämonen... sie... sie sammeln sich... bereiten sich vor...\n\nMusste fliehen... die anderen warnen. Wir müssen... sie aufhalten!", sourceObjective = "Sprecht mit Taktikerin Zunderschlag.", completion = "Seid gegrüßt, Meisterjäger. Mir wurde gerade von der verwundeten Soldatin berichtet, die von der Verheerten Küste fliehen konnte.\n\nIch will mir gar nicht ausmalen, was sie alles durchgemacht haben muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[46023] = { id = 46023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Zunderschlag senkt ihren Blick.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
