quests[46028] = { id = 46028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Warnung", description = "<Die Soldatin ist verwundet und blass im Gesicht. Offensichtlich hat sie große Schmerzen.>\n\nHielten mich gefangen... seit dem Angriff auf... die Verheerte Küste...\n\n<Sie zittert.>\n\nDie Dämonen... sie... sie sammeln sich... bereiten sich vor...\n\nMusste fliehen... die anderen warnen. Wir müssen... sie aufhalten!", sourceObjective = "Sprecht mit Moira Thaurissan.", sourceObjectiveStatus = "unverified-source-field" }
quests[46029] = { id = 46029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Moira senkt ihren Blick.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46030] = { id = 46030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Warnung", description = "<Der Soldat ist verwundet und blass im Gesicht. Offensichtlich hat er große Schmerzen.>\n\nSie... hielten mich gefangen... seit dem Angriff auf... die Verheerte Küste...\n\n<Er zittert.>\n\nDie Dämonen... sie... sie sammeln sich... bereiten sich vor...\n\nMusste fliehen... Euch warnen. Wir müssen... sie aufhalten!", sourceObjective = "Sprecht mit Siouxsie der Banshee.", completion = "Seid gegrüßt, Todesgebieter. Mir wurde gerade von dem verwundeten Soldaten berichtet, der von der Verheerten Küste fliehen konnte.\n\nIch will mir gar nicht ausmalen, was er alles durchgemacht haben muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[46031] = { id = 46031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Verheerten Küste", description = "Wir alle wissen um den Preis, den wir bezahlen mussten, als wir das letzte Mal die Verheerte Küste betreten haben.\n\n<Siouxsie senkt ihren Blick.>\n\nIch empfehle, eine Gruppe Kundschafter auszusenden, um mehr über die Truppenstärke der Legion zu erfahren. Wir müssen wissen, was uns an diesem vermaledeiten Ort erwartet.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Bedrohung an der Verheerten Küste\" ab.", completion = "Das sind wahrlich keine guten Neuigkeiten.\n\nIch schlage vor, dass wir unsere Champions weiterhin nach möglichen Gefahren Ausschau halten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46032] = { id = 46032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peinvolle Rückkehr" }
quests[46034] = { id = 46034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Aelthalyste", sourceObjective = "All diese {class} sind Euch unterstellt? Das ist in der Tat bemerkenswert.\n\nIch habe nur einen, Roland, und bei Euch scheinen es hunderte zu sein!\n\nIch glaube, wir werden gut miteinander auskommen, {name}. Sehr gut sogar.\n\nWenn Ihr mir erlaubt zu bleiben, will ich Euch gern meine Dienste anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[46035] = { id = 46035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der erwachten Bedrohung", description = "Kommandant Schattensang lässt mitteilen, dass er für die Konfrontation mit dem verstorbenen Lord Erdris bereit ist. Ich soll Euch diesen Brief von ihm übergeben.\n\nIch bin bereit, Euch zu ihm zu schicken, doch es gibt noch einen Haken.\n\nUm gegen das Schlimmste der Teufelsverderbnis anzukämpfen, benötigt ihr beim Eintritt Nethersplitter. Stellt also sicher, dass Ihr welche bei Euch habt, bevor Ihr mich ansprecht.", sourceObjective = "Besiegt Lord Erdris Dorn. Sprecht mit Kriegsrätin Victoria, um zum Standort von Jarod Schattensang teleportiert zu werden.", completion = "Eine weitere Krise abgewendet! Eure Effektivität ist unvergleichlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[46036] = { id = 46036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadnaught's Battlegear" }
quests[46037] = { id = 46037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ymirjar's Battlegear" }
quests[46038] = { id = 46038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ymirjar's Battlegear" }
quests[46039] = { id = 46039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ymirjar's Battlegear" }
quests[46040] = { id = 46040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlegear of Iron Wrath" }
quests[46041] = { id = 46041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlegear of Iron Wrath" }
quests[46042] = { id = 46042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlegear of Iron Wrath" }
quests[46043] = { id = 46043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Aethas Sonnenhäscher", sourceObjective = "Erzmagier, die Ereignisse der Vergangenheit waren lange Zeit eine schwere Bürde für mich. Ich bereue zwar nicht meine Taten, aber dennoch ihre Folgen. Wenn ich sie nur ungeschehen machen könnte...\n\nIch hoffe, dass die Kirin Tor, und ganz Azeroth, irgendwann den Wert meiner Treue besser verstehen werden. Dank Euch konnte die Krise abgewendet werden. Ihr habt meinen ewigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[46044] = { id = 46044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thisalee Krähe", sourceObjective = "Hört mal, Erzdruide, versteht mich nicht falsch. Ich liebe Aviana. Sie ist meine Ahnin! Aber sie ist ein bisschen zu passiv, als dass ich ihr ständig hinterherlaufen möchte.\n\nIhr auf der anderen Seite... Ihr seid genau richtig! Ich will mitten im Geschehen sein und irgendeinem Dämon den Tag vermiesen!\n\nUnd? Werdet Ihr mich mitnehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[46045] = { id = 46045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nerus Mondfang", sourceObjective = "Ich weiß, ich habe viel zu verantworten.\n\nObwohl ich meine Familie vom Fluch befreit habe, kann nichts die Schmerzen lindern, die meine Fehler ihr zugefügt haben.\n\nEs war eine gute Entscheidung von Delas, sich der Silbernen Hand zu verschreiben. Ich hoffe, das, was ich damals tat, ändert nichts an Eurer Wertschätzung für sie.\n\nIch würde es Delas gerne gleichtun und Eurem Orden meine Unterstützung bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[46046] = { id = 46046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger-Lich" }
quests[46047] = { id = 46047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kanrethad Schwarzhaupt", sourceObjective = "Auch wenn ich mich nicht ganz klar an die jüngsten Ereignisse erinnere, werde ich nie die Macht vergessen, die ich in Euch sehen konnte, als Ihr Rezara bezwungen habt.\n\nDeshalb war es auch die richtige Entscheidung des Rates, Euch während meiner Abwesenheit als Anführer zu erwählen.\n\nMacht Euch keine Sorgen, ich habe kein Verlangen, gegen diese Entscheidung zu argumentieren. Ich schulde Euch mein Leben.\n\nLasst mich Euch und dem Rat dienen. Es gibt noch so viel, was wir voneinander lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[46048] = { id = 46048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nachtjägerin Syrenne", sourceObjective = "Sagt mir, {name}, sind all Eure Anhänger so hingebungsvoll wie ihr Anführer?\n\nEs fällt mir nie leicht, Außenstehenden zu trauen, doch wir beide sind uns recht ähnlich, nicht wahr? Wir scheuen keine Mühen, um jenes zu schützen, was uns lieb und teuer ist. In dieser Hinsicht verfolgen wir dasselbe Ziel.\n\nIch würde Euch und Eure {class} gerne unterstützen, sofern Ihr es mir erlaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46049] = { id = 46049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk von Eurer Kaulquappe", sourceObjective = "<Eure Kaulquappe hat ein Geschenk für Euch. Was wohl drin ist?>", sourceObjectiveStatus = "unverified-source-field" }
quests[46050] = { id = 46050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Minerva Rabenkummer", sourceObjective = "Hört mal, auch wenn ich untot sein mag und meine Lungen keinen Zweck mehr erfüllen, war es wie ein Hauch frischer Luft, Daumyr in den Untod zu erwecken. Ich bitte Euch, mich weiterhin anzuleiten. Führt mich wieder in die Schlacht! Ich werde die Knochen jedes Dämons, der auch nur in meine Richtung blickt, in alle Winde zerstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46051] = { id = 46051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 01" }
quests[46052] = { id = 46052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 02" }
quests[46053] = { id = 46053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 03" }
quests[46054] = { id = 46054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 04" }
quests[46055] = { id = 46055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 05" }
quests[46057] = { id = 46057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Magatha Grimmtotem", sourceObjective = "Ihr seid ein närrisches Kind. Ihr glaubt, über große Macht zu verfügen, doch wisst Ihr nichts. Das großartige Potenzial des Verdammnissteins sollte ausgenutzt werden! Er verkümmert, solange er im Mahlstrom weilt.\n\nVielleicht war es ein Fehler, hierherzukommen. Nobundo verlangt, dass die Grimmtotems bleiben. Ich bleibe aus persönlichen Gründen, nicht, weil er darum gebeten hat. Wenn Ihr von mir oder meinen Kriegern erwartet, unseren Unterhalt zu verdienen, werden wir es tun.\n\nAber werdet nicht hochmütig.", sourceObjectiveStatus = "unverified-source-field" }
quests[46058] = { id = 46058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lilian Voss", sourceObjective = "Mit diesen Dämonen habt Ihr kurzen Prozess gemacht und ich hoffe, Ihr werdet das noch mit vielen weiteren tun. Solange die Legion ihren Einfluss in unserer Welt ausweitet, wird sie auch weiterhin unsere Leute verderben.\n\nIch würde gerne weiter mit Euch zusammenarbeiten, um diesem Wahnsinn ein Ende zu setzen. Meine Klingen gehören Euch, Schattenklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[46059] = { id = 46059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Tess Graumähne", sourceObjective = "Ihr habt mir Euer Können viele Male bewiesen, Schattenklinge. Meine Kollegen haben Euch bereits ihrer Dienste versichert, aber ich habe mich zurückgehalten. Zwar schreiten alle Schurken durch die Schatten, doch ist es von entscheidender Bedeutung, dass mein Status absolut geheim bleibt.\n\nDie Bedrohung ist allerdings zu gravierend. Wir sind so nah daran, der Legion einen entscheidenden Schlag zu versetzen... und ich will eine größere Rolle dabei spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46060] = { id = 46060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errettung", description = "Das Tal wimmelt nur so von teufelsverderbten Tieren, die nicht mehr zu retten sind. Doch es gibt vielleicht noch einige, die unsere Hilfe brauchen könnten.\n\nNehmt diese Manawurzelsalbe und tragt sie bei allen Tieren auf, die Ihr seht. Wenn die Teufelsmagie sich noch nicht festgesetzt hat, könnte die Salbe vielleicht ihre Wunden heilen.", sourceObjective = "Benutzt die Manawurzelsalbe bei teufelsinfizierten Tieren.", completion = "Ihr habt Euer Leben riskiert, um diese Tiere vor einem Leben zu bewahren, das schlimmer ist als der Tod. Ich preise Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[46061] = { id = 46061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adoptiert eine Kaulquappe", description = "Für einen Tag des Jahres, für gewöhnlich im Mittfrühling, können die Kaulquappen im Dorf tun und lassen, was sie wollen. Ich weiß nicht, wieso sich diese Tradition hält, denn üblicherweise führt das nur zu verwüsteten Hütten und Lebensmittelständen.\n\nIch versuche normalerweise, mich nicht in Angelegenheiten des Stammes einzumischen, aber heute mache ich eine Ausnahme. Seht, ob Ihr eine der Kaulquappen im Auge behalten könnt.", sourceObjective = "Wählt Euren Favoriten unter den Kaulquappen der Winterflossen und bringt sie dazu, Euch zu folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46062] = { id = 46062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will, ich will, ich will!", description = "Glrrrr! Mrr, mrr, glrrgli!\n\n<Euer kleiner Kaulquappenliebling wird ungestüm. Vielleicht will er ein paar Muscheln?>", sourceObjective = "Besorgt 10 Winterflossenmuscheln.", sourceObjectiveStatus = "unverified-source-field" }
quests[46063] = { id = 46063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die klagenden Toten" }
